#!/usr/bin/env python3
"""One-off native integration capture; all AWS mutations are uniquely owned."""
import argparse
import base64
import datetime
import hashlib
import json
import os
from pathlib import Path
import tempfile
import time
import traceback
import uuid

from aws_cli import call, AWSCLIError, run, result

ROOT = Path(__file__).resolve().parents[2]
DEST = ROOT / "testdata/aws/stepfunctions/task_integrations.json"
REGION = "us-west-2"
ACCOUNT = "000000000000"
ENV = dict(os.environ, AWS_DEFAULT_REGION=REGION, AWS_REGION=REGION, AWS_PAGER="")
SOURCE = Path(__file__).read_text()
SECRETS = {}
F = {}


def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def discover_secrets(value):
    if isinstance(value, dict):
        for key, item in value.items():
            if key.lower() in ("tasktoken", "token", "receipthandle") and isinstance(item, str) and item and not item.startswith("<redacted-"):
                SECRETS.setdefault(item, "<redacted-" + key.lower() + "-" + hashlib.sha256(item.encode()).hexdigest()[:12] + ">")
            discover_secrets(item)
    elif isinstance(value, list):
        for item in value:
            discover_secrets(item)
    elif isinstance(value, str) and value[:1] in ("{", "["):
        try:
            discover_secrets(json.loads(value))
        except json.JSONDecodeError:
            pass


def clean(value):
    discover_secrets(value)
    text = json.dumps(value, ensure_ascii=False)
    for secret, replacement in SECRETS.items():
        text = text.replace(json.dumps(secret, ensure_ascii=False)[1:-1], replacement)
        text = text.replace(json.dumps(json.dumps(secret, ensure_ascii=False)[1:-1])[1:-1], replacement)
    return json.loads(text)


def save():
    DEST.write_text(json.dumps(clean(F), indent=2, ensure_ascii=False) + "\n")


def observe(label, service, operation, parameters=None):
    row = {"label": label, "service": service, "operation": operation,
           "region": REGION if service not in ("iam", "sts") else "aws-global",
           "input": parameters or {}, "started_at": now()}
    try:
        out = call(service, operation, parameters, ENV, error_format="json", paginate=False)
        row["result"] = {"code": "Success", "output": out}
    except AWSCLIError as error:
        out = None
        row["result"] = {"code": error.details["Code"], "error": error.details}
    row["finished_at"] = now()
    F["observations"].append(clean(row))
    save()
    return out


def required(label, service, operation, parameters=None):
    out = observe(label, service, operation, parameters)
    if out is None:
        raise RuntimeError("Required call failed: " + label)
    return out


def task(resource, parameters, **extra):
    return dict(Type="Task", Resource="arn:aws:states:::" + resource,
                Parameters=parameters, TimeoutSeconds=25, End=True, **extra)


def one(state):
    return {"StartAt": "Task", "TimeoutSeconds": 40, "States": {"Task": state}}


def definition(states):
    return {"StartAt": "Case", "TimeoutSeconds": 90,
            "States": {"Case": {"Type": "Choice", "Choices": [
                {"Variable": "$.case", "StringEquals": key, "Next": key} for key in states],
                "Default": "Unsupported"}, "Unsupported": {"Type": "Fail", "Error": "UnknownProbeCase"}, **states}}


def update(label, arn, body, role=None):
    args = {"stateMachineArn": arn, "definition": json.dumps(body)}
    if role:
        args["roleArn"] = role
    out = observe(label, "stepfunctions", "update-state-machine", args)
    if out is not None:
        time.sleep(3)
    return out


def begin(label, machine, data):
    if len(F["executions"]) >= 24:
        raise RuntimeError("Execution bound reached")
    out = required(label + "-start", "stepfunctions", "start-execution", {
        "stateMachineArn": machine, "name": label + "-" + uuid.uuid4().hex[:6], "input": json.dumps(data)})
    arn = out["executionArn"]
    F["executions"].append({"label": label, "arn": arn})
    save()
    return arn


def finish(label, arn, limit=100):
    deadline = time.monotonic() + limit
    out = None
    while time.monotonic() < deadline:
        out = required(label + "-describe-" + str(int(time.monotonic())), "stepfunctions", "describe-execution", {"executionArn": arn})
        if out["status"] != "RUNNING":
            break
        time.sleep(2)
    if out is None or out["status"] == "RUNNING":
        required(label + "-bounded-stop", "stepfunctions", "stop-execution", {"executionArn": arn, "error": "ProbeDeadline", "cause": "Bounded native capture"})
        out = required(label + "-after-stop", "stepfunctions", "describe-execution", {"executionArn": arn})
    history = required(label + "-history", "stepfunctions", "get-execution-history", {"executionArn": arn, "includeExecutionData": True, "maxResults": 1000})
    F["cases"][label] = {"executionArn": arn, "status": out["status"], "history_label": label + "-history"}
    for key in ("output", "error", "cause"):
        if key in out:
            F["cases"][label][key] = out[key]
    if history.get("nextToken"):
        raise RuntimeError("Unexpected history pagination")
    save()
    return out


def execute(label, machine, data=None, limit=100):
    return finish(label, begin(label, machine, data or {"case": label, "null": None}), limit)


def setup():
    identity = required("identity", "sts", "get-caller-identity")
    if identity["Account"] != ACCOUNT or not identity["Arn"].endswith(":user/Delegated"):
        raise RuntimeError("Unexpected native account/caller")
    prefix = F["prefix"]
    r = F["resources"]
    r.update(bucket=prefix, queue_name=prefix, primary_role_name=prefix + "-exec", task_role_name=prefix + "-task")
    r["primary_role_arn"] = f"arn:aws:iam::{ACCOUNT}:role/{r['primary_role_name']}"
    r["task_role_arn"] = f"arn:aws:iam::{ACCOUNT}:role/{r['task_role_name']}"
    save()
    if not r.get("bucket_created"):
        required("create-bucket", "s3api", "create-bucket", {"Bucket": r["bucket"], "CreateBucketConfiguration": {"LocationConstraint": REGION}})
        r["bucket_created"] = True
        save()
    if "queue_url" not in r:
        q = required("create-queue", "sqs", "create-queue", {"QueueName": r["queue_name"], "Attributes": {"MessageRetentionPeriod": "600"}})
        r["queue_url"] = q["QueueUrl"]
        r["queue_arn"] = f"arn:aws:sqs:{REGION}:{ACCOUNT}:{prefix}"
        save()
    primary_trust = {"Version": "2012-10-17", "Statement": [{"Effect": "Allow", "Principal": {"Service": "states.amazonaws.com"},
        "Action": "sts:AssumeRole", "Condition": {"StringEquals": {"aws:SourceAccount": ACCOUNT}, "ArnLike": {"aws:SourceArn": f"arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{prefix}*"}}}]}
    task_trust = {"Version": "2012-10-17", "Statement": [{"Effect": "Allow", "Principal": {"AWS": r["primary_role_arn"]}, "Action": "sts:AssumeRole"}]}
    if not r.get("primary_role_created"):
        required("create-primary-role", "iam", "create-role", {"RoleName": r["primary_role_name"], "AssumeRolePolicyDocument": json.dumps(primary_trust)})
        r["primary_role_created"] = True
        save()
        time.sleep(12)
    if not r.get("task_role_created"):
        required("create-untrusted-execution-role", "iam", "create-role", {"RoleName": r["task_role_name"], "AssumeRolePolicyDocument": json.dumps(task_trust)})
        r["task_role_created"] = True
        save()
    policy = {"Version": "2012-10-17", "Statement": [
        {"Effect": "Allow", "Action": ["s3:PutObject", "s3:GetObject"], "Resource": f"arn:aws:s3:::{prefix}/*"},
        {"Effect": "Allow", "Action": "s3:ListBucket", "Resource": f"arn:aws:s3:::{prefix}"},
        {"Effect": "Allow", "Action": ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes"], "Resource": r["queue_arn"]},
        {"Effect": "Allow", "Action": "sts:AssumeRole", "Resource": r["task_role_arn"]},
        {"Effect": "Allow", "Action": "states:StartExecution", "Resource": f"arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{prefix}-child"},
        {"Effect": "Allow", "Action": ["states:DescribeExecution", "states:StopExecution"], "Resource": f"arn:aws:states:{REGION}:{ACCOUNT}:execution:{prefix}-child:*"}]}
    F["policies"] = {"primary": policy, "primary_trust": primary_trust, "task_trust": task_trust}
    required("put-primary-policy-no-eventbridge", "iam", "put-role-policy", {"RoleName": r["primary_role_name"], "PolicyName": "owned", "PolicyDocument": json.dumps(policy)})
    time.sleep(12)
    states = {
        "s3-flow": task("aws-sdk:s3:putObject", {"Bucket": prefix, "Key": "text", "Body": "hello\nπ", "ContentType": "text/plain; charset=utf-8", "Metadata": {"Mixed-Key": "MixedValue"}, "Expires": "2030-01-02T03:04:05Z"}),
        "s3-empty-list": task("aws-sdk:s3:listObjectsV2", {"Bucket": prefix, "Prefix": "absent/", "MaxKeys": 2}),
        "s3-no-such-key": task("aws-sdk:s3:getObject", {"Bucket": prefix, "Key": "absent"}),
        "s3-null-body": task("aws-sdk:s3:putObject", {"Bucket": prefix, "Key": "null", "Body": None, "ContentType": None}),
        "s3-base64-body": task("aws-sdk:s3:putObject", {"Bucket": prefix, "Key": "base64", "Body": "AP9BQgo="}),
        "sqs-sdk-cycle": task("aws-sdk:sqs:sendMessage", {"QueueUrl": r["queue_url"], "MessageBody": "sdk-message", "MessageAttributes": {"Binary": {"DataType": "Binary", "BinaryValue": "AP9BQgo="}, "Str": {"DataType": "String", "StringValue": "mixed"}}}),
        "sqs-sdk-target-error": task("aws-sdk:sqs:sendMessage", {"QueueUrl": r["queue_url"], "MessageBody": "invalid-delay", "DelaySeconds": 901}),
        "sqs-optimized-request-response": task("sqs:sendMessage", {"QueueUrl": r["queue_url"], "MessageBody": {"source": "optimized", "nullable": None}}),
        "sqs-optimized-callback": task("sqs:sendMessage.waitForTaskToken", {"QueueUrl": r["queue_url"], "MessageBody": {"source": "optimized-callback", "TaskToken.$": "$$.Task.Token", "Payload.$": "$"}}),
        "sqs-sdk-callback": task("aws-sdk:sqs:sendMessage.waitForTaskToken", {"QueueUrl": r["queue_url"], "MessageBody.$": "States.JsonToString($)"}),
        "credentials-success": task("aws-sdk:sqs:sendMessage", {"QueueUrl": r["queue_url"], "MessageBody": "credentials-success"}, Credentials={"RoleArn": r["task_role_arn"]}),
        "credentials-denied": task("aws-sdk:s3:getObject", {"Bucket": prefix, "Key": "text"}, Credentials={"RoleArn": r["task_role_arn"]})}
    states["sqs-sdk-callback"]["Parameters"]["MessageBody.$"] = "States.JsonToString($$.Task)"
    for key, nxt, rp in (("s3-flow", "S3Get", "$.put"), ("s3-base64-body", "S3Base64Get", "$.put"), ("sqs-sdk-cycle", "SQSReceive", "$.send")):
        states[key].pop("End")
        states[key].update(Next=nxt, ResultPath=rp)
    states["S3Get"] = task("aws-sdk:s3:getObject", {"Bucket": prefix, "Key": "text"})
    states["S3Get"].pop("End")
    states["S3Get"].update(Next="S3List", ResultPath="$.get")
    states["S3List"] = task("aws-sdk:s3:listObjectsV2", {"Bucket": prefix, "MaxKeys": 10}, ResultPath="$.list")
    states["S3Base64Get"] = task("aws-sdk:s3:getObject", {"Bucket": prefix, "Key": "base64"}, ResultPath="$.get")
    states["SQSReceive"] = task("aws-sdk:sqs:receiveMessage", {"QueueUrl": r["queue_url"], "MaxNumberOfMessages": 1, "MessageAttributeNames": ["All"], "MessageSystemAttributeNames": ["All"], "WaitTimeSeconds": 1}, ResultPath="$.receive")
    F["definitions"] = {"primary": definition(states), "child": {"StartAt": "Wait", "TimeoutSeconds": 10, "States": {"Wait": {"Type": "Wait", "Seconds": 1, "Next": "Echo"}, "Echo": {"Type": "Pass", "Parameters": {"child": "ok", "input.$": "$", "nullable": None}, "End": True}}}, "auth": one(task("aws-sdk:sqs:sendMessage", {"QueueUrl": r["queue_url"], "MessageBody": "auth-probe"}))}
    for name in ("child", "primary", "auth"):
        role = r["task_role_arn"] if name == "auth" else r["primary_role_arn"]
        out = observe("create-" + name, "stepfunctions", "create-state-machine", {"name": prefix + "-" + name, "roleArn": role, "type": "STANDARD", "definition": json.dumps(F["definitions"][name])})
        if out is not None:
            r[name + "_machine"] = out["stateMachineArn"]
            save()
    if not all(name + "_machine" in r for name in ("child", "primary", "auth")):
        raise RuntimeError("One or more machine definitions failed admission")
    F["setup_complete"] = True
    save()


def drain(label, callback=False):
    r = F["resources"]
    deadline = time.monotonic() + (18 if callback else 4)
    while time.monotonic() < deadline:
        out = required(label + "-receive-" + str(int(time.monotonic())), "sqs", "receive-message", {"QueueUrl": r["queue_url"], "MaxNumberOfMessages": 10, "WaitTimeSeconds": 1, "VisibilityTimeout": 30, "MessageAttributeNames": ["All"], "MessageSystemAttributeNames": ["All"]})
        for message in out.get("Messages", []):
            body = message.get("Body", "")
            parsed = json.loads(body) if body.startswith("{") else {}
            token = parsed.get("TaskToken") or parsed.get("Token")
            if token and callback:
                SECRETS.setdefault(token, "<redacted-tasktoken-" + hashlib.sha256(token.encode()).hexdigest()[:12] + ">")
                required(label + "-heartbeat", "stepfunctions", "send-task-heartbeat", {"taskToken": token})
                required(label + "-callback", "stepfunctions", "send-task-success", {"taskToken": token, "output": json.dumps({"worker": "actual-sqs-receipt", "nullable": None, "array": [1, "two"]})})
            required(label + "-delete-message", "sqs", "delete-message", {"QueueUrl": r["queue_url"], "ReceiptHandle": message["ReceiptHandle"]})
            if token and callback:
                return True
        if not callback and not out.get("Messages"):
            return False
    return False


def direct_object(key):
    with tempfile.TemporaryDirectory(prefix="stackd-sfn-object-") as directory:
        path = Path(directory) / "object"
        p = run("s3api", "get-object", None, ENV, options=["--bucket", F["resources"]["bucket"], "--key", key, str(path)], timeout=40)
        row = {"label": "direct-s3-body-" + key, "service": "s3api", "operation": "get-object", "input": {"Bucket": F["resources"]["bucket"], "Key": key}, "result": result(p, cli_message=None)}
        if p.returncode == 0:
            body = path.read_bytes()
            row["body_bytes"] = {"base64": base64.b64encode(body).decode(), "length": len(body), "sha256": hashlib.sha256(body).hexdigest()}
            try:
                row["body_bytes"]["utf8"] = body.decode()
            except UnicodeDecodeError:
                pass
        F["observations"].append(row)
        save()


def byte_cases():
    for key in ("text", "null", "base64"):
        direct_object(key)


def data_cases():
    r = F["resources"]
    for label in ("s3-flow", "s3-empty-list", "s3-no-such-key", "s3-null-body", "s3-base64-body", "sqs-sdk-cycle", "sqs-sdk-target-error", "sqs-optimized-request-response"):
        execute(label, r["primary_machine"])
        if label.startswith("sqs-"):
            drain(label)
    for key in ("text", "null", "base64"):
        direct_object(key)
    for label in ("sqs-optimized-callback", "sqs-sdk-callback"):
        arn = begin(label, r["primary_machine"], {"case": label, "null": None})
        F["callback_receipts"][label] = drain(label, callback=True)
        finish(label, arn, limit=40)
    wrong = one(task("aws-sdk:s3:putObject", {"bucket": r["bucket"], "Key": "not-written", "Body": "lower-case"}))
    observe("sdk-lowercase-parameter-admission", "stepfunctions", "validate-state-machine-definition", {"definition": json.dumps(wrong), "type": "STANDARD", "severity": "WARNING"})
    F["data_complete"] = True
    save()


def auth_cases():
    r = F["resources"]
    execute("execution-role-no-states-trust", r["auth_machine"])
    missing = f"arn:aws:iam::{ACCOUNT}:role/{F['prefix']}-not-created"
    if update("auth-missing-role-update", r["auth_machine"], F["definitions"]["auth"], missing):
        execute("execution-role-missing", r["auth_machine"])
    states_trust = F["policies"]["primary_trust"]
    required("task-role-states-trust-no-permissions", "iam", "update-assume-role-policy", {"RoleName": r["task_role_name"], "PolicyDocument": json.dumps(states_trust)})
    time.sleep(12)
    update("auth-permissionless-role-update", r["auth_machine"], F["definitions"]["auth"], r["task_role_arn"])
    execute("execution-role-no-target-permissions", r["auth_machine"])
    required("task-role-credentials-trust", "iam", "update-assume-role-policy", {"RoleName": r["task_role_name"], "PolicyDocument": json.dumps(F["policies"]["task_trust"])})
    policy = {"Version": "2012-10-17", "Statement": [{"Effect": "Allow", "Action": "sqs:SendMessage", "Resource": r["queue_arn"]}]}
    F["policies"]["task"] = policy
    required("task-role-send-only-policy", "iam", "put-role-policy", {"RoleName": r["task_role_name"], "PolicyName": "owned", "PolicyDocument": json.dumps(policy)})
    time.sleep(12)
    for label in ("credentials-success", "credentials-denied"):
        execute(label, r["primary_machine"])
    drain("credentials-drain")
    F["auth_complete"] = True
    save()


def capture_children(label):
    r = F["resources"]
    out = required(label + "-children", "stepfunctions", "list-executions", {"stateMachineArn": r["child_machine"], "maxResults": 100})
    known = {x["arn"] for x in F["executions"]}
    for child in out["executions"]:
        if child["executionArn"] not in known:
            child_label = label + "-child-" + child["name"]
            F["executions"].append({"label": child_label, "arn": child["executionArn"]})
            finish(child_label, child["executionArn"], limit=20)
    save()


def nested_cases():
    r = F["resources"]
    nested = {}
    for mode in ("request-response", "sync", "sync2"):
        suffix = {"request-response": "", "sync": ".sync", "sync2": ".sync:2"}[mode]
        nested["nested-" + mode] = task("states:startExecution" + suffix, {"StateMachineArn": r["child_machine"], "Input": {"from": mode, "nullable": None}}, **{})
        nested["nested-" + mode]["TimeoutSeconds"] = 65
    body = definition(nested)
    F["definitions"]["nested"] = body
    accepted = update("nested-no-eventbridge-update", r["primary_machine"], body)
    F["nested_no_eventbridge_admitted"] = accepted is not None
    if accepted is None:
        F["nested_blocker"] = "Native UpdateStateMachine rejected nested sync without EventBridge permissions; no shared managed rule changes authorized. RequestResponse remains independently observable."
        rr = definition({"nested-request-response": nested["nested-request-response"]})
        if update("nested-request-response-only-update", r["primary_machine"], rr):
            execute("nested-request-response", r["primary_machine"])
            capture_children("nested-request-response")
    else:
        for label in nested:
            execute(label, r["primary_machine"], limit=80)
            capture_children(label)
        # Reserve two executions requested for actual Pass/Assign/Choice evidence.
        if len(F["executions"]) + 4 <= 24:
            no_polling = json.loads(json.dumps(F["policies"]["primary"]))
            no_polling["Statement"] = [x for x in no_polling["Statement"] if x["Action"] != ["states:DescribeExecution", "states:StopExecution"]]
            required("remove-owned-child-polling-permissions", "iam", "put-role-policy", {"RoleName": r["primary_role_name"], "PolicyName": "owned", "PolicyDocument": json.dumps(no_polling)})
            time.sleep(12)
            execute("nested-sync-without-polling", r["primary_machine"], {"case": "nested-sync"}, limit=80)
            capture_children("nested-sync-without-polling")
    F["nested_complete"] = True
    save()


def recreate_nested():
    r = F["resources"]
    F["recreation_reason"] = "Parent expanded managed-rule authority after teardown had already initiated machine deletion. Cleanup was cancelled before roles/queue/bucket deletion; only the same primary+child machine ARNs are recreated."
    required("recovery-primary-role-exists", "iam", "get-role", {"RoleName": r["primary_role_name"]})
    pending = ["primary_machine", "child_machine"]
    for attempt in range(45):
        for key in list(pending):
            observe("recovery-await-absence-" + key + "-" + str(attempt), "stepfunctions", "describe-state-machine", {"stateMachineArn": r[key]})
            if F["observations"][-1]["result"]["code"] == "StateMachineDoesNotExist":
                pending.remove(key)
        if not pending:
            break
        time.sleep(4)
    if pending:
        raise RuntimeError("Machine deletion has not completed")
    for key in ("child", "primary"):
        body = F["definitions"]["child"] if key == "child" else {"StartAt": "Done", "States": {"Done": {"Type": "Succeed"}}}
        out = required("recreate-original-" + key, "stepfunctions", "create-state-machine", {"name": F["prefix"] + "-" + key, "roleArn": r["primary_role_arn"], "type": "STANDARD", "definition": json.dumps(body)})
        if out["stateMachineArn"] != r[key + "_machine"]:
            raise RuntimeError("Unexpected replacement identity")
    F["recreated_machine_arns"] = [r["primary_machine"], r["child_machine"]]
    save()


def nested_managed():
    r = F["resources"]
    name = "StepFunctionsGetEventsForStepFunctionsExecutionRule"
    rule = observe("managed-rule-before", "events", "describe-rule", {"Name": name})
    if rule is None:
        if F["observations"][-1]["result"]["code"] != "ResourceNotFoundException":
            raise RuntimeError("Cannot establish native managed-rule absence")
        F["managed_rule_owned"] = True
        F["managed_targets_before"] = {"Targets": []}
        rule = {"Name": name, "Arn": f"arn:aws:events:{REGION}:{ACCOUNT}:rule/{name}"}
    elif rule.get("ManagedBy") != "states.amazonaws.com":
        raise RuntimeError("Existing rule is not Step Functions managed")
    else:
        F["managed_rule_owned"] = False
        F["managed_targets_before"] = required("managed-targets-before", "events", "list-targets-by-rule", {"Rule": name})
    F["managed_rule"] = rule
    authorized = json.loads(json.dumps(F["policies"]["primary"]))
    authorized["Statement"].append({"Effect": "Allow", "Action": ["events:PutRule", "events:PutTargets", "events:DescribeRule"], "Resource": rule["Arn"]})
    required("grant-exact-native-managed-rule", "iam", "put-role-policy", {"RoleName": r["primary_role_name"], "PolicyName": "owned", "PolicyDocument": json.dumps(authorized)})
    time.sleep(12)
    branches = []
    for mode in ("sync", "sync:2"):
        state = task("states:startExecution." + mode, {"StateMachineArn": r["child_machine"], "Input": {"from": mode, "nullable": None}})
        state["TimeoutSeconds"] = 75
        state_name = "Nested" + mode.replace(":", "").title()
        branches.append({"StartAt": state_name, "States": {state_name: state}})
    single = task("states:startExecution.sync:2", {"StateMachineArn": r["child_machine"], "Input": {"from": "without-polling", "nullable": None}})
    single["TimeoutSeconds"] = 20
    single.pop("End")
    single["Next"] = "Expose"
    body = {"StartAt": "Seed", "TimeoutSeconds": 90, "States": {
        "Seed": {"Type": "Pass", "Result": {"marker": "raw", "selected": {"marker": "selected"}}, "Next": "AssignStages"},
        "AssignStages": {"Type": "Pass", "InputPath": "$.selected", "Parameters": {"marker": "parameters"},
                         "Result": {"marker": "result", "selection": {"marker": "output"}}, "ResultPath": "$.placed", "OutputPath": "$.placed.selection",
                         "Assign": {"staged.$": "$", "stageField.$": "$.marker"}, "Next": "RememberStages"},
        "RememberStages": {"Type": "Pass", "QueryLanguage": "JSONata", "Assign": {"stageObservation": "{% {'seen': $staged, 'field': $stageField, 'output': $states.input} %}"},
                           "Output": "{% $states.context.Execution.Input %}", "Next": "Choose"},
        "Choose": {"Type": "Choice", "Choices": [{"Variable": "$.case", "StringEquals": "pair", "Next": "Pair"}], "Default": "Single"},
        "Pair": {"Type": "Parallel", "Branches": branches, "Next": "Expose"},
        "Single": single,
        "Expose": {"Type": "Pass", "QueryLanguage": "JSONata", "Output": {"stage": "{% $stageObservation %}", "nested": "{% $states.input %}"}, "End": True}}}
    F["definitions"]["nested-managed"] = body
    if update("nested-managed-admission", r["primary_machine"], body) is None:
        raise RuntimeError("Exact managed-rule scoped admission still failed")
    F["managed_rule_created"] = required("managed-rule-after-admission", "events", "describe-rule", {"Name": name})
    F["managed_targets_created"] = required("managed-targets-after-admission", "events", "list-targets-by-rule", {"Rule": name})
    required("remove-eventbridge-grants-retain-polling", "iam", "put-role-policy", {"RoleName": r["primary_role_name"], "PolicyName": "owned", "PolicyDocument": json.dumps(F["policies"]["primary"])})
    time.sleep(20)
    execute("nested-pair-no-eventbridge-polling", r["primary_machine"], {"case": "pair"}, limit=100)
    capture_children("nested-pair-no-eventbridge-polling")
    observe("managed-targets-after-pair", "events", "list-targets-by-rule", {"Rule": name})
    no_polling = json.loads(json.dumps(F["policies"]["primary"]))
    no_polling["Statement"] = [x for x in no_polling["Statement"] if x["Action"] != ["states:DescribeExecution", "states:StopExecution"]]
    required("remove-polling-and-eventbridge-grants", "iam", "put-role-policy", {"RoleName": r["primary_role_name"], "PolicyName": "owned", "PolicyDocument": json.dumps(no_polling)})
    time.sleep(20)
    execute("nested-no-eventbridge-no-polling", r["primary_machine"], {"case": "single"}, limit=35)
    capture_children("nested-no-eventbridge-no-polling")
    F["nested_managed_complete"] = True
    F["nested_permission_limitation"] = "Native managed rule was admitted with exact ARN grants, then grants were removed before execution; this does not alone establish whether completion used existing event delivery or DescribeExecution polling."
    save()


def pure_cases():
    machine = F["resources"]["primary_machine"]
    body = {"StartAt": "Null", "States": {
        "Null": {"Type": "Pass", "Result": None, "Next": "Remember"},
        "Remember": {"Type": "Pass", "QueryLanguage": "JSONata", "Assign": {"nullObservation": "{% $states.input %}"}, "Output": {"marker": "raw", "selected": {"marker": "selected"}}, "Next": "Assign"},
        "Assign": {"Type": "Pass", "InputPath": "$.selected", "Parameters": {"marker": "parameters", "origin.$": "$.marker"},
                   "Result": {"marker": "result"}, "ResultPath": "$.placed", "OutputPath": "$.placed",
                   "Assign": {"seen.$": "$", "field.$": "$.marker"}, "Next": "Expose"},
        "Expose": {"Type": "Pass", "QueryLanguage": "JSONata", "Output": {
            "nullObserved": "{% $nullObservation %}", "assignSeen": "{% $seen %}",
            "assignField": "{% $field %}", "stateInput": "{% $states.input %}"}, "End": True}}}
    F["definitions"]["pure-null-assign"] = body
    required("pure-null-assign-validation", "stepfunctions", "validate-state-machine-definition", {"definition": json.dumps(body)})
    if update("pure-null-assign-update", machine, body):
        execute("pure-null-assign", machine, {"marker": "raw", "selected": {"marker": "selected"}})
    choice = {"QueryLanguage": "JSONata", "StartAt": "Seed", "States": {
        "Seed": {"Type": "Pass", "Assign": {"shared": "seed", "stateOnly": "seed", "ruleOnly": "seed", "noRule": "seed"}, "Next": "Selected"},
        "Selected": {"Type": "Choice", "Assign": {"shared": "state", "stateOnly": "state"}, "Output": {"source": "state-output"},
                     "Choices": [{"Condition": "{% true %}", "Assign": {"shared": "rule", "ruleOnly": "rule"}, "Output": {"source": "rule-output"}, "Next": "RememberSelected"}], "Default": "RememberSelected"},
        "RememberSelected": {"Type": "Pass", "Assign": {"selectedSeen": "{% {'shared': $shared, 'stateOnly': $stateOnly, 'ruleOnly': $ruleOnly, 'input': $states.input} %}"}, "Next": "MatchedNoAssign"},
        "MatchedNoAssign": {"Type": "Choice", "Assign": {"noRule": "state-assignment"}, "Choices": [{"Condition": "{% true %}", "Next": "DefaultOnly"}], "Default": "DefaultOnly"},
        "DefaultOnly": {"Type": "Choice", "Assign": {"defaultSeen": "default-assignment"}, "Output": {"source": "default-output"},
                        "Choices": [{"Condition": "{% false %}", "Next": "Expose"}], "Default": "Expose"},
        "Expose": {"Type": "Pass", "Output": {"selected": "{% $selectedSeen %}", "matchedWithoutAssign": "{% $noRule %}", "default": "{% $defaultSeen %}", "input": "{% $states.input %}"}, "End": True}}}
    F["definitions"]["pure-choice"] = choice
    validation = required("pure-choice-validation", "stepfunctions", "validate-state-machine-definition", {"definition": json.dumps(choice)})
    if validation["result"] != "OK":
        raise RuntimeError("Choice precedence definition rejected; preserve native diagnostics")
    if update("pure-choice-update", machine, choice):
        execute("pure-choice", machine, {"original": True})
    F["pure_complete"] = True
    save()


def cleanup():
    r = F["resources"]
    # Enumerate only the three owned machines, including child executions.
    for key in ("primary_machine", "auth_machine", "child_machine"):
        if key not in r:
            continue
        listed = observe("cleanup-" + key + "-all-executions", "stepfunctions", "list-executions", {"stateMachineArn": r[key], "maxResults": 100})
        if listed is not None:
            for execution in listed["executions"]:
                if execution["status"] == "RUNNING":
                    observe("cleanup-stop-" + execution["name"], "stepfunctions", "stop-execution", {"executionArn": execution["executionArn"], "error": "ProbeCleanup"})
            running = required("cleanup-" + key + "-running", "stepfunctions", "list-executions", {"stateMachineArn": r[key], "statusFilter": "RUNNING", "maxResults": 100})
            F["cleanup"][key + "_no_running"] = not running["executions"]
        observe("cleanup-delete-" + key, "stepfunctions", "delete-state-machine", {"stateMachineArn": r[key]})
    if r.get("bucket_created"):
        listing = observe("cleanup-list-objects", "s3api", "list-objects-v2", {"Bucket": r["bucket"]})
        if listing is not None:
            for item in listing.get("Contents", []):
                required("cleanup-delete-object-" + item["Key"], "s3api", "delete-object", {"Bucket": r["bucket"], "Key": item["Key"]})
            empty = required("cleanup-empty-bucket", "s3api", "list-objects-v2", {"Bucket": r["bucket"]})
            F["cleanup"]["objects_absent"] = empty.get("KeyCount") == 0
            required("cleanup-delete-bucket", "s3api", "delete-bucket", {"Bucket": r["bucket"]})
        observe("cleanup-bucket-absent", "s3api", "head-bucket", {"Bucket": r["bucket"]})
        F["cleanup"]["bucket_absent"] = F["observations"][-1]["result"]["code"] in ("404", "NoSuchBucket", "NotFound")
    if "queue_url" in r:
        observe("cleanup-delete-queue", "sqs", "delete-queue", {"QueueUrl": r["queue_url"]})
        observe("cleanup-queue-absent", "sqs", "get-queue-url", {"QueueName": r["queue_name"]})
        F["cleanup"]["queue_absent"] = F["observations"][-1]["result"]["code"] in ("AWS.SimpleQueueService.NonExistentQueue", "QueueDoesNotExist")
    for label in ("primary", "task"):
        if r.get(label + "_role_created"):
            observe("cleanup-delete-policy-" + label, "iam", "delete-role-policy", {"RoleName": r[label + "_role_name"], "PolicyName": "owned"})
            observe("cleanup-delete-role-" + label, "iam", "delete-role", {"RoleName": r[label + "_role_name"]})
            observe("cleanup-role-absent-" + label, "iam", "get-role", {"RoleName": r[label + "_role_name"]})
            F["cleanup"][label + "_role_absent"] = F["observations"][-1]["result"]["code"] == "NoSuchEntity"
    pending = [key for key in ("primary_machine", "auth_machine", "child_machine") if key in r]
    for attempt in range(45):
        for key in list(pending):
            observe("cleanup-absence-" + key + "-" + str(attempt), "stepfunctions", "describe-state-machine", {"stateMachineArn": r[key]})
            if F["observations"][-1]["result"]["code"] == "StateMachineDoesNotExist":
                F["cleanup"][key + "_absent"] = True
                pending.remove(key)
        if not pending:
            break
        time.sleep(4)
    for execution in F["executions"]:
        observe("cleanup-execution-absent-" + execution["label"], "stepfunctions", "describe-execution", {"executionArn": execution["arn"]})
        F["cleanup"]["execution_absent_" + execution["label"]] = F["observations"][-1]["result"]["code"] == "ExecutionDoesNotExist"
    if "managed_rule" in F:
        name = F["managed_rule"]["Name"]
        F["managed_rule_after_cleanup"] = observe("managed-rule-after-cleanup", "events", "describe-rule", {"Name": name})
        F["managed_targets_after_cleanup"] = observe("managed-targets-after-cleanup", "events", "list-targets-by-rule", {"Rule": name})
        if F["managed_rule_after_cleanup"] is None and F["observations"][-1]["result"]["code"] == "ResourceNotFoundException":
            F["cleanup"]["managed_rule_absent"] = True
        elif F.get("managed_rule_owned") and not pending:
            current = F["managed_rule_after_cleanup"]
            targets = F["managed_targets_after_cleanup"]
            expected = F["managed_targets_created"]
            if current and current.get("ManagedBy") == "states.amazonaws.com" and targets is not None and all(x in expected.get("Targets", []) for x in targets.get("Targets", [])):
                if targets.get("Targets"):
                    removed = required("cleanup-owned-managed-targets", "events", "remove-targets", {"Rule": name, "Ids": [x["Id"] for x in targets["Targets"]], "Force": True})
                    if removed.get("FailedEntryCount"):
                        raise RuntimeError("Owned native target cleanup failed")
                required("cleanup-owned-managed-rule", "events", "delete-rule", {"Name": name, "Force": True})
                observe("cleanup-owned-managed-rule-absent", "events", "describe-rule", {"Name": name})
                F["cleanup"]["managed_rule_absent"] = F["observations"][-1]["result"]["code"] == "ResourceNotFoundException"
            else:
                F["cleanup"]["managed_rule_absent"] = False
                F["managed_rule_retained_reason"] = "ManagedBy or target inventory changed; refusing unrelated deletion."
        else:
            F["cleanup"]["managed_targets_unchanged"] = F["managed_targets_after_cleanup"] == F["managed_targets_before"]
    F["cleanup_complete"] = not pending and all(F["cleanup"].values())
    F["finished_at"] = now()
    save()


def finalize():
    if not F.get("cleanup_complete"):
        raise RuntimeError("Cleanup absence evidence is incomplete")
    observations = F["observations"]
    histories = {row["label"]: row["result"]["output"]["events"] for row in observations
                 if row["operation"] == "get-execution-history" and row["result"]["code"] == "Success"}
    for execution in F["executions"]:
        if not F["cleanup"].get("execution_absent_" + execution["label"]):
            raise RuntimeError("Execution absence not confirmed")
    machine_creates = [row for row in observations if row["operation"] == "create-state-machine" and row["result"]["code"] == "Success"]
    F["capture_totals"] = {
        "distinct_machine_arns": len({row["result"]["output"]["stateMachineArn"] for row in machine_creates}),
        "machine_create_calls": len(machine_creates),
        "role_create_calls": sum(row["operation"] == "create-role" and row["result"]["code"] == "Success" for row in observations),
        "execution_count_including_nested": len(F["executions"]),
        "execution_absence_confirmations": sum(key.startswith("execution_absent_") and value for key, value in F["cleanup"].items()),
        "note": "Only original primary/child ARNs were recreated after teardown/revised parent authorization crossed in flight; no fourth distinct or simultaneous machine."}
    if len(F["executions"]) > 24:
        raise RuntimeError("Execution bound violated")
    pair = json.loads(F["cases"]["nested-pair-no-eventbridge-polling"]["output"])
    F["contracts"] = {
        "sdk_sqs": {"case": "sqs-sdk-cycle", "output": json.loads(F["cases"]["sqs-sdk-cycle"]["output"])},
        "optimized_sqs": {"case": "sqs-optimized-request-response", "output": json.loads(F["cases"]["sqs-optimized-request-response"]["output"])},
        "s3_body_bytes": [row for row in observations if row["label"].startswith("direct-s3-body-") and row["result"]["code"] == "Success"],
        "error_names": {key: {"error": value["error"], "history_label": value["history_label"]} for key, value in F["cases"].items() if "error" in value},
        "callback_event_types": {key: [e["type"] for e in histories[key + "-history"]] for key in ("sqs-optimized-callback", "sqs-sdk-callback")},
        "nested_sync": {"case": "nested-pair-no-eventbridge-polling", "output_types": [type(x["Output"]).__name__ for x in pair["nested"]], "output": pair["nested"]},
        "assign_processing_stage": pair["stage"],
        "pure_null_assign": json.loads(F["cases"]["pure-null-assign"]["output"]),
        "pure_choice": json.loads(F["cases"]["pure-choice"]["output"])}
    F["limitations"] = [
        "CLI normalizes top-level modeled API dates; TaskSucceeded payload strings retain native integration date and casing representations.",
        "No SNS topic was needed; SQS supplies optimized RequestResponse and both optimized/SDK real token callbacks.",
        "The definition containing both sync variants required managed-rule authority for admission; runtime comparisons occur only after native rule creation. Twenty-second IAM pauses do not prove all caches converged, and completion transport cannot be inferred solely from role policy.",
        "Initial IAM principal propagation failure, CLI download argument failures, invalid duplicate branch names, teardown interruption and source revisions are retained without deleting observations."]
    F["nested_blocker_resolved"] = F.get("nested_managed_complete", False)
    F["completed"] = True
    save()


def main():
    global F
    parser = argparse.ArgumentParser()
    parser.add_argument("phase", choices=["setup", "data", "bytes", "auth", "nested", "recreate-nested", "nested-managed", "pure", "cleanup", "finalize"])
    args = parser.parse_args()
    if DEST.exists():
        F = json.loads(DEST.read_text())
        if F["source"]["text"] != SOURCE:
            F.setdefault("source_revisions", []).append(F["source"])
    else:
        F = {"service": "stepfunctions", "account": ACCOUNT, "region": REGION,
             "prefix": "stackd-sfn-task-" + uuid.uuid4().hex[:10], "captured_at": now(),
             "transport": "AWS CLI through scripts/aws/aws_cli.py; native TaskScheduled/TaskSucceeded/history JSON string content preserved. CLI normalizes top-level modeled timestamps; those are not claimed as wire timestamps.",
             "redaction": "Only actual task tokens and SQS receipt handles replaced by stable SHA256-labeled placeholders; account IDs, resource ARNs and payload bytes retained.",
             "bounds": {"machines": 3, "roles": 2, "buckets": 1, "queues": 1, "topics": 0, "total_parent_and_child_executions": 24, "child_wait_seconds": 1},
             "resources": {}, "observations": [], "cases": {}, "executions": [], "callback_receipts": {}, "cleanup": {},
             "official_urls": ["https://docs.aws.amazon.com/step-functions/latest/dg/supported-services-awssdk.html", "https://docs.aws.amazon.com/step-functions/latest/dg/connect-sqs.html", "https://docs.aws.amazon.com/step-functions/latest/dg/connect-stepfunctions.html"]}
    F["source"] = {"path": str(Path(__file__).relative_to(ROOT)), "text": SOURCE}
    save()
    try:
        {"setup": setup, "data": data_cases, "bytes": byte_cases, "auth": auth_cases, "nested": nested_cases, "recreate-nested": recreate_nested, "nested-managed": nested_managed, "pure": pure_cases, "cleanup": cleanup, "finalize": finalize}[args.phase]()
    except BaseException:
        F.setdefault("probe_errors", []).append({"phase": args.phase, "traceback": traceback.format_exc(), "at": now()})
        save()
        raise
    print(json.dumps(clean({"phase": args.phase, "cases": F["cases"], "executions": len(F["executions"]), "cleanup": F.get("cleanup_complete")})))


if __name__ == "__main__":
    main()

